import java.util.HashSet;
import java.util.Scanner;

public class Main {
    static long[] parentArray = new long[1100000];

    static long findRepresentative(long x) {
        if (parentArray[(int) x] == x) return x;
        parentArray[(int) x] = findRepresentative(parentArray[(int) x]);
        return parentArray[(int) x];
    }

    static void unionRepresentatives(long x, long y) {
        if (findRepresentative(x) == findRepresentative(y)) return;
        parentArray[(int) findRepresentative(x)] = findRepresentative(y);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        for (long i = 0; i < p; i++) {
            parentArray[(int) i] = i;
        }

        for (long i = 1; i < p; i++) {
            if ((k * i) % p != 0) {
                unionRepresentatives((k * i) % p, i);
            }
        }

        HashSet<Long> distinctGroups = new HashSet<>();
        for (long i = 1; i < p; i++) {
            distinctGroups.add(findRepresentative(i));
        }

        long groupCount = (k == 1) ? p : distinctGroups.size();

        long resultValue = 1;
        for (long i = 0; i < groupCount; i++) {
            resultValue = (resultValue * p) % 1000000007;
        }

        System.out.println(resultValue);
        sc.close();
    }
}
